/* Growth desk. Uses the app's existing Supabase session, owner guard, cards and toast. */
const GC=GrowthCore;
const GR={owner:null,loaded:false,loading:false,busy:false,error:null,settings:null,channels:[],weeks:[],selected:null,biz:'combined',panel:'pots',businesses:[],subscriptions:[],payments:[],pots:[],flowWeeks:[],payouts:[],editSubscription:null,paymentRetry:null,payoutRetry:null,detailsOpen:false,budgetPeriod:'week',modal:null,charts:{},chartVersion:0,observer:null,bodyOverflow:null};
function grOwner(){if(!CURRENT_USER_ID||CURRENT_PROFILE.role!=='owner')throw Error('Owner access is required.');return CURRENT_USER_ID;}
function grMoney(n){return new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',minimumFractionDigits:Number(n)%1===0?0:2,maximumFractionDigits:2}).format(n);}
function grWeek(){if(!GR.selected)GR.selected=GC.monday(GC.day(new Date()));const start=(GR.settings||GC.defaults).start_date;return GR.selected<GC.monday(start)?GC.monday(start):GR.selected;}
function grRefresh(){if(currentRoute==='growth')renderPage();}
async function grAll(table,owner){const rows=[];for(let from=0;;from+=1000){let q=sb.from(table).select('*').eq('owner_id',owner);const orders={growth_weeks:['week_start','channel_id'],growth_channels:['ladder_order'],growth_payments:['payment_date','id'],growth_subscriptions:['business','id'],growth_businesses:['business'],growth_pots:['week_start','business','pot'],growth_flow_weeks:['week_start'],growth_payouts:['paid_date','id']};for(const k of orders[table]||['owner_id'])q=q.order(k);const {data,error}=await q.range(from,from+999);if(error)throw error;rows.push(...(data||[]));if(!data||data.length<1000)return rows;}}
async function grLoad(){if(GR.loading)return;let owner;try{owner=grOwner();}catch(e){return;}GR.loading=true;GR.error=null;if(GR.owner!==owner){GR.loaded=false;GR.settings=null;GR.channels=[];GR.weeks=[];GR.selected=null;GR.businesses=[];GR.subscriptions=[];GR.payments=[];GR.pots=[];GR.flowWeeks=[];GR.payouts=[];GR.paymentRetry=null;GR.payoutRetry=null;GR.editSubscription=null;}
 try{const [settings,channels,weeks,businesses,subscriptions,payments,pots,flowWeeks,payouts]=await Promise.all(['growth_settings','growth_channels','growth_weeks','growth_businesses','growth_subscriptions','growth_payments','growth_pots','growth_flow_weeks','growth_payouts'].map(t=>grAll(t,owner)));if(grOwner()!==owner)return;GR.owner=owner;GR.settings=settings[0]||null;GR.channels=channels;GR.weeks=weeks;GR.businesses=businesses;GR.subscriptions=subscriptions;GR.payments=payments;GR.pots=pots;GR.flowWeeks=flowWeeks;GR.payouts=payouts;GR.loaded=true;}catch(e){GR.loaded=false;GR.error=e.message||String(e);}finally{GR.loading=false;grRefresh();}}
async function grRun(fn){if(GR.busy)return;GR.busy=true;grSetModalBusy();try{await fn();}catch(e){toast(e.message||'Could not save','⚠️');}finally{GR.busy=false;grSetModalBusy();grRefresh();}}
function grInitialise(){return grRun(async()=>{const owner=grOwner();const {error}=await sb.from('growth_settings').upsert(Object.assign({owner_id:owner},GC.defaults),{onConflict:'owner_id',ignoreDuplicates:true});if(error)throw error;const result=await sb.from('growth_channels').upsert(GC.channels.map(c=>Object.assign({owner_id:owner},c)),{onConflict:'owner_id,id',ignoreDuplicates:true});if(result.error)throw result.error;const br=await sb.from('growth_businesses').upsert(GC.businesses.map(b=>({owner_id:owner,...b})),{onConflict:'owner_id,business',ignoreDuplicates:true});if(br.error)throw br.error;const sr=await sb.from('growth_subscriptions').upsert(GC.businesses.flatMap(b=>GC.subscriptionNames.map(name=>({owner_id:owner,business:b.business,name,seed_key:name}))),{onConflict:'owner_id,business,seed_key',ignoreDuplicates:true});if(sr.error)throw sr.error;if(grOwner()!==owner)return;await grLoad();toast('Growth defaults created');});}
function grValue(id){const el=grEl(id);if(!el)throw Error('Reload Growth before saving.');return el.value;}
function grFormWeek(id){const old=GR.weeks.find(r=>r.channel_id===id&&r.week_start===grWeek());const r={channel_id:id,week_start:grWeek(),ticks:Object.assign({},old&&old.ticks)};
 for(const k of ['spend','leads','quotes','wins','revenue','materials','labour','cash_received','hours_used','booked_hours','available_hours'])r[k]=grValue('gr-'+id+'-'+k);
 for(const [k] of GC.checklist)r.ticks[k]=document.getElementById('gr-'+id+'-tick-'+k).checked;
 for(const k of ['resume_channel','review_cap'])r.ticks[k]=document.getElementById('gr-'+id+'-tick-'+k).checked;
 r.notes=grValue('gr-'+id+'-notes').trim();return GC.week(r);
}
function grPreview(id){try{const raw=grFormWeek(id),r=GC.effectiveWeeks([raw],grActivePayments().filter(p=>p.channel_id===id&&GC.monday(p.payment_date)===raw.week_start))[0],funds=GC.cash(r,GC.settings(GR.settings));document.getElementById('gr-'+id+'-preview').textContent='Profit '+grMoney(r.profit)+' · '+GC.light(r)+' · cash-received profit '+grMoney(funds.profit_received);}catch(e){document.getElementById('gr-'+id+'-preview').textContent=e.message;}}
function grSaveWeek(event,id){event.preventDefault();return grRun(async()=>{const owner=grRequireData();await grPersistWeek(owner,grFormWeek(id));toast('Channel week saved');});}
function grSaveSettings(event){event.preventDefault();return grRun(async()=>{const owner=grOwner();if(GR.owner!==owner||!GR.settings)throw Error('Reload Growth first.');const patch={};for(const k of Object.keys(GC.defaults))patch[k]=k==='deadline'?null:grValue('gr-setting-'+k);patch.vat_enabled=document.getElementById('gr-setting-vat_enabled').checked;const valid=GC.settings(patch);valid.updated_at=new Date().toISOString();const {data,error}=await sb.from('growth_settings').update(valid).eq('owner_id',owner).eq('updated_at',GR.settings.updated_at).select('*').maybeSingle();if(error||!data)throw error||Error('Settings changed in another tab. Reload first.');if(grOwner()!==owner)return;GR.settings=data;toast('Growth settings saved');});}
function grSaveChannel(event,id){event.preventDefault();return grRun(async()=>{const owner=grOwner(),c=GR.channels.find(c=>c.id===id);if(GR.owner!==owner||!c)throw Error('Reload Growth first.');const patch={active:document.getElementById('gr-active-'+id).checked,capped:document.getElementById('gr-capped-'+id).checked,updated_at:new Date().toISOString()};const {data,error}=await sb.from('growth_channels').update(patch).eq('owner_id',owner).eq('id',id).eq('updated_at',c.updated_at).select('*').maybeSingle();if(error||!data)throw error||Error('Channel changed in another tab. Reload first.');if(grOwner()!==owner)return;Object.assign(c,data);toast('Channel settings saved');});}
function grSelect(value){try{GC.date(value);if(GC.monday(value)!==value)throw Error('Choose the Monday starting the earning week.');if(value<GC.monday(GR.settings.start_date))throw Error('Choose a week on or after the tracker start.');GR.selected=value;grRefresh();}catch(e){toast(e.message,'⚠️');}}
function grContractor(){try{const r=GC.contractor(grValue('gr-job-price'),grValue('gr-contractor-cost'),GR.settings);document.getElementById('gr-contractor-result').textContent=(r.allowed?'Within budget. ':'Too much for this price. ')+'Most to pay: '+grMoney(r.maximum_cost);}catch(e){document.getElementById('gr-contractor-result').textContent=e.message;}}
function grField(id,label,value,extra){return `<label class="form-group">${esc(label)}<input id="${esc(id)}" type="number" min="0" step="0.01" value="${value==null?'':esc(value)}" ${extra||''}></label>`;}
function grCard(result){const c=result.channel,id=c.id,r=GR.weeks.find(x=>x.channel_id===id&&x.week_start===grWeek())||{},ticks=r.ticks||{};const m=result.multiple==null?'No lead cost yet':result.multiple.toFixed(2)+'x profit on leads';
 const fields=[['spend',r.ticks&&r.ticks.lead_topups?'Lead top-ups this week (£)':'Other lead spend (£)'],['leads','Leads'],['quotes','Quotes sent'],['wins','Jobs or clients won'],['revenue','Revenue (£)'],['materials','Materials (£)'],['labour','Contractor labour (£)'],['cash_received','Cash received (£)'],['hours_used','Hours used'],['booked_hours','Booked delivery hours'],['available_hours','Hours available for this channel']];
 return `<section class="card"><div class="card-title"><span>${esc(c.ladder_order)}. ${esc(c.name)}</span><span class="gr-light gr-${result.light}">${esc(result.light)}</span></div><p class="small muted">${esc(m)} · Cost per job ${result.cost_per_win==null?'—':grMoney(result.cost_per_win)}${result.paused?' · Paused':''}</p>${result.reasons.length?`<p class="gr-notice">${esc(result.reasons.map(grReason).join(' · '))}</p>`:''}<div class="gr-recommendation">Next week: <strong>${grMoney(result.next_spend)}</strong></div><p class="small muted">Lead cost recovered ${grMoney(result.spend_recovered)}<br>Tax ${grMoney(result.tax_pot)} · Overheads ${grMoney(result.overheads||0)} · Owner Pay ${grMoney(result.owner_pay||0)} · buffer ${grMoney(result.buffer)}${result.overflow_in?' · moved from another channel '+grMoney(result.overflow_in):''}</p>
 ${grEffectiveNotice(id)}<form onsubmit="grSaveWeek(event,'${esc(id)}')"><fieldset ${GR.busy?'disabled':''}><div class="gr-fields">${fields.map(([k,l])=>grField('gr-'+id+'-'+k,l,r[k],`oninput="grPreview('${esc(id)}')" ${['leads','quotes','wins'].includes(k)?'inputmode="numeric"':''}`)).join('')}</div><output class="gr-preview" id="gr-${esc(id)}-preview">Profit from these entries ${grMoney(r.profit||0)}</output><p class="small muted">Count shared hours once; leave unknowns blank.</p><div class="gr-checks">${GC.checklist.map(([k,l])=>`<label><input type="checkbox" id="gr-${esc(id)}-tick-${k}" ${ticks[k]?'checked':''}> ${esc(k==='tax'?GR.settings.tax_pct+'% after bills set aside for Tax':({recorded:'Profit and payments entered',light:'Channel results checked',spend:'Next week’s lead spend set',buffer:'Buffer topped up',capacity:'Do I need a contractor?',total:'Profit total updated'})[k]||l)}</label>`).join('')}</div><details><summary>Restart a channel</summary>${[['resume_channel','I have checked the pause and want to restart'],['review_cap','I have checked the low returns and want to restart']].map(([k,l])=>`<label class="gr-check"><input type="checkbox" id="gr-${esc(id)}-tick-${k}" ${ticks[k]?'checked':''}> ${l}</label>`).join('')}<p class="small muted">Switches below still apply.</p></details><label class="form-group">Notes<textarea id="gr-${esc(id)}-notes" rows="3">${esc(r.notes||'')}</textarea></label><button class="btn btn-gold" type="submit">Save channel week</button></fieldset></form>
 <details class="gr-channel-settings"><summary>Channel settings</summary><form onsubmit="grSaveChannel(event,'${esc(id)}')"><label class="gr-check"><input id="gr-active-${esc(id)}" type="checkbox" ${c.active?'checked':''}> Active</label><label class="gr-check"><input id="gr-capped-${esc(id)}" type="checkbox" ${c.capped?'checked':''}> No more suitable leads</label><button class="btn btn-ghost btn-sm" ${GR.busy?'disabled':''}>Save channel settings</button></form></details></section>`;
}
const GR_BIZ={sf:'Steady Flow',sw:'SteadyWorks',combined:'Combined'};
const GR_METRICS=[['outreach_sent','Outreach sent'],['replies','Replies'],['calls_booked','Calls booked'],['proposals','Proposals'],['sales','Sales'],['websites_delivered','Websites delivered'],['monthly_clients_active','Monthly clients active'],['clients_500_plus','Clients paying £500+ monthly'],['mrr','Monthly income (£)']];
function grActivePayments(){return GC.activePayments(GR.payments);}
function grRows(){return GC.effectiveWeeks(GR.weeks,GR.payments);}
function grBusiness(c){return c.business||(c.id==='steadyflow'?'sf':'sw');}
function grBizRows(rows){return GR.biz==='combined'?rows:rows.filter(r=>GR.channels.some(c=>c.id===r.channel_id&&grBusiness(c)===GR.biz));}
function grTab(biz){if(!Object.hasOwn(GR_BIZ,biz))return;GR.biz=biz;GR.editSubscription=null;grRefresh();}
function grPanel(panel){if(panel==='tracker')panel='channels';if(!GR_DETAIL_TABS.some(r=>r[0]===panel))return;GR.panel=panel;GR.detailsOpen=true;grRefresh();}
function grTable(headers,rows,empty){return `<div class="gr-table"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${esc(empty||'No entries yet.')}</td></tr>`}</tbody></table></div>`;}
function grOptions(options,value){return options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');}
function grText(id,label,value,type='text'){return `<label>${esc(label)}<input id="${esc(id)}" type="${type}" value="${esc(value||'')}"></label>`;}
function grSelectField(id,label,options,value,change=''){return `<label>${esc(label)}<select id="${esc(id)}" ${change}>${grOptions(options,value)}</select></label>`;}
function grEffectiveNotice(id){const paid=grActivePayments().filter(p=>p.channel_id===id&&GC.monday(p.payment_date)===grWeek());return paid.length?`<p class="gr-help">${paid.length} payment${paid.length===1?'':'s'} included; clear matching unpaid entries.</p>`:'<p class="gr-help">Other work and unpaid amounts only.</p>';}
function grPaymentInput(){return GC.payment({business:grValue('gr-pay-business'),channel_id:grValue('gr-pay-channel'),payment_type:grValue('gr-pay-type'),payment_date:grValue('gr-pay-date'),amount:grValue('gr-pay-amount'),materials:grValue('gr-pay-materials'),labour:grValue('gr-pay-labour'),lead_cost:grValue('gr-pay-lead_cost'),notes:grValue('gr-pay-notes').trim()});}
function grSavePayment(event){event.preventDefault();return grRun(async()=>{const owner=grOwner();if(GR.owner!==owner||!GR.loaded)throw Error('Reload Growth first.');const p=grPaymentInput();if(p.payment_date<GR.settings.start_date||p.payment_date>GC.day(new Date()))throw Error('Choose a receipt date from the tracker start through today.');
 // Preserve this UUID for retries after a timeout. The server returns the same receipt once.
 const fingerprint=JSON.stringify(p);if(!GR.paymentRetry||GR.paymentRetry.fingerprint!==fingerprint)GR.paymentRetry={fingerprint,id:crypto.randomUUID()};
 const args={p_id:GR.paymentRetry.id};for(const [k,v] of Object.entries(p))args['p_'+k]=v;const {data,error}=await sb.rpc('growth_save_payment',args);if(error)throw error;if(!data)throw Error('Payment was not returned. Reload before retrying.');if(data.voided_at!=null)throw Error('Payment reference is voided. Reload before entering the correction.');if(grOwner()!==owner)return;GR.paymentRetry=null;GR.selected=GC.monday(p.payment_date);grCloseModal();await grLoad();toast('Payment saved; weekly totals updated');});}
function grPots(){const biz=GR.biz==='combined'?['sf','sw']:[GR.biz],w=grWeek(),rows=[];for(const b of biz){const totals=GC.paymentTotals(GR.payments,w,b),summary=GC.subscriptions(GR.subscriptions,b,GC.day(new Date())),config=GR.businesses.find(r=>r.business===b),target=GR.pots.find(r=>r.business===b&&r.week_start===w&&r.pot==='Growth');
 for(const pot of GC.pots.filter(k=>k!=='VAT'||grVatNear()||GR.settings.vat_enabled)){let t=pot==='Overheads'?summary.weekly:pot==='Owner Pay'?Number(config&&config.owner_pay_target||0):pot==='Growth'?Number(target&&target.target_amount||0):null;rows.push([esc(GR_BIZ[b]),grPotName(pot),grMoney(totals.allocations[pot]),t==null?'—':grMoney(t),pot==='Growth'?'Extra money, after recovered lead costs':pot==='Main'?'Nothing left after the split':'']);}}
 return `<section class="card"><h2>Pots · ${esc(w)}</h2><p class="small muted">Tax pots: one company. This week: ${grMoney(GC.paymentTotals(GR.payments,w).allocations.Tax)}. Company Tax total: ${grMoney(grActivePayments().reduce((n,p)=>n+Number((p.allocations||{}).Tax||0),0))}.</p>${grTable(['Business','Pot','Set aside this week','Weekly target','Note'],rows)}<p>Friday: ${esc(grDate(GC.shift(w,4)))}. £250 maximum, when funded.</p><p>Owner Pay: ${grMoney(GC.paymentTotals(GR.payments,w).paid_out)} / £250. Paid: ${grMoney(GR.payouts.filter(r=>GR.biz==='combined'||r.business===GR.biz).reduce((n,r)=>n+Number(r.amount),0))}.</p><form onsubmit="grSaveGrowthTarget(event)"><div class="gr-fields">${grSelectField('gr-pot-business','Business',biz.map(b=>[b,GR_BIZ[b]]),biz[0])}${grField('gr-pot-target','Extra Growth target for next week (£)',Number((GR.pots.find(r=>r.business===biz[0]&&r.week_start===w&&r.pot==='Growth')||{}).target_amount||0))}</div><button class="btn btn-ghost" ${GR.busy?'disabled':''}>Save Growth target</button></form><p class="small muted">Monthly bills × 12 ÷ 52. Add missing prices.</p><details><summary>Record a Friday pay-out already made</summary><p class="small muted">Record past pay; ask your accountant about payroll or dividends.</p><form onsubmit="grSavePayout(event)"><div class="gr-fields">${grSelectField('gr-payout-business','Business',biz.map(b=>[b,GR_BIZ[b]]),biz[0])}${grText('gr-payout-date','Date paid',GC.day(new Date()),'date')}${grField('gr-payout-amount','Amount already paid (£)','')}</div><button class="btn btn-ghost" ${GR.busy?'disabled':''}>Record pay-out</button></form></details></section>`;}
function grSaveGrowthTarget(event){event.preventDefault();return grRun(async()=>{const owner=grOwner(),b=GC.payment({business:grValue('gr-pot-business'),channel_id:grValue('gr-pot-business')==='sf'?'steadyflow':'myjobquote',payment_type:grValue('gr-pot-business')==='sf'?'website':'job',payment_date:grWeek(),amount:1}).business;const amount=Number(grValue('gr-pot-target'));if(!Number.isFinite(amount)||amount<0)throw Error('Enter a non-negative target.');const {error}=await sb.rpc('growth_save_pot_target',{p_business:b,p_week:grWeek(),p_target:amount});if(error)throw error;if(grOwner()===owner)await grLoad();toast('Growth target saved');});}
function grSavePayout(event){event.preventDefault();return grRun(async()=>{const owner=grOwner(),args={p_business:grValue('gr-payout-business'),p_date:grValue('gr-payout-date'),p_amount:Number(grValue('gr-payout-amount'))};if(!GR.payoutRetry||GR.payoutRetry.fingerprint!==JSON.stringify(args))GR.payoutRetry={id:crypto.randomUUID(),fingerprint:JSON.stringify(args)};const {error}=await sb.rpc('growth_record_payout',{p_id:GR.payoutRetry.id,...args});if(error)throw error;if(grOwner()!==owner)return;GR.payoutRetry=null;grCloseModal();await grLoad();toast('Pay-out recorded');});}
function grVatNear(){const today=GC.day(new Date()),cutoff=GC.shift(today,-365);return grActivePayments().filter(p=>p.payment_date>=cutoff&&p.payment_date<=today).reduce((n,p)=>n+Number(p.amount),0)>=81000;}
function grVoidPayment(id){if(GR.busy)return;let owner;try{owner=grOwner();if(GR.owner!==owner||!GR.loaded)throw Error('Reload Growth first.');const receipt=GR.payments.find(p=>p.id===id);if(!receipt||receipt.voided_at!=null)throw Error('Choose an active saved payment.');}catch(e){toast(e.message,'⚠️');return;}
 const reason=prompt('Why void this payment? The original receipt stays in the audit history. This does not make a refund.','');if(reason===null)return;
 return grRun(async()=>{if(grOwner()!==owner)throw Error('Reload Growth first.');const preview=GC.voidPreview(GR.payments,GR.payouts,id,reason,owner);const {data,error}=await sb.rpc('growth_void_payment',{p_id:id,p_reason:preview.reason});if(error)throw error;if(!data||data.voided_at==null)throw Error('Void was not confirmed. Reload before retrying.');if(grOwner()!==owner)return;GR.paymentRetry=null;await grLoad();toast('Payment voided; pots and weekly totals updated');});
}
function grPayments(){const list=GR.payments.filter(p=>(GR.biz==='combined'||p.business===GR.biz)&&GC.monday(p.payment_date)===grWeek()).sort((a,b)=>b.payment_date.localeCompare(a.payment_date));return `<section class="card"><h2>Saved payments</h2><p class="small muted">Void mistakes; originals stay. No refund; recorded pay stays protected.</p>${grTable(['Received','Business','Type','Cash','Profit','Owner Pay','Growth','Notes','State / action'],list.map(p=>[esc(p.payment_date),esc(GR_BIZ[p.business]),esc(p.payment_type),grMoney(p.amount),grMoney(p.profit),grMoney((p.allocations||{})['Owner Pay']||0),grMoney((p.allocations||{}).Growth||0),esc(p.notes||''),p.voided_at!=null?'Voided '+esc(p.voided_at)+'<br>'+esc(p.void_reason||''):`<button class="btn btn-danger btn-sm" ${GR.busy?'disabled':''} onclick="grVoidPayment('${esc(p.id)}')">Void</button>`]))}</section>`;}
function grSubscriptions(){const today=GC.day(new Date()),list=GR.subscriptions.filter(r=>GR.biz==='combined'||r.business===GR.biz),b=GR.biz==='combined'?'sf':GR.biz,r=GR.subscriptions.find(r=>r.id===GR.editSubscription)||{business:b,billing_cycle:'monthly',status:'review'},summary=GC.subscriptions(list,null,today);return `<section class="card"><h2>Subscriptions</h2><div class="gr-totals">${(GR.biz==='combined'?['sf','sw']:[GR.biz]).map(b=>{const s=GC.subscriptions(list,b,today);return `<span>${esc(GR_BIZ[b])} monthly<strong>${grMoney(s.monthly)}</strong>Overheads ${grMoney(s.weekly)} / week</span>`;}).join('')}</div><p>${summary.unknown} blank prices · ${summary.per_use} per-use costs excluded · ${summary.review.length} marked review</p><h3>Renewals in the next 14 days</h3>${grTable(['Business','Name','Renewal','Cost'],summary.renewals.map(r=>[esc(GR_BIZ[r.business]),esc(r.name),esc(r.next_renewal),r.cost==null?'Unknown':grMoney(r.cost)]))}<h3>Marked for review</h3>${grTable(['Business','Name','Notes'],summary.review.map(r=>[esc(GR_BIZ[r.business]),esc(r.name),esc(r.notes||'')]))}<h3>Subscription register</h3>${grTable(['Business','Name / purpose','Cost / cycle','Renewal','Paid from','Rebilled','Status','Notes',''],list.map(r=>[esc(GR_BIZ[r.business]),esc(r.name)+'<br>'+esc(r.purpose||''),r.cost==null?'Price not entered':grMoney(r.cost)+' / '+esc(r.billing_cycle),esc(r.next_renewal||''),esc(r.paid_from||''),r.client_rebilled?'Yes: '+esc(r.client_name):'No',esc(r.status),esc(r.notes||''),`<button class="btn btn-ghost btn-sm" onclick="grEditSubscription('${esc(r.id)}')">Edit</button>`]))}<h3>${r.id?'Edit':'Add'} subscription</h3><form onsubmit="grSaveSubscription(event)"><fieldset ${GR.busy?'disabled':''}><div class="gr-fields">${grSelectField('gr-sub-business','Business',[['sf','Steady Flow'],['sw','SteadyWorks']],r.business)}${grText('gr-sub-name','Name',r.name)}${grText('gr-sub-purpose','Purpose',r.purpose)}${grField('gr-sub-cost','Cost (£, leave unknown blank)',r.cost)}${grSelectField('gr-sub-billing_cycle','Billing cycle',['monthly','yearly','per use'].map(k=>[k,k]),r.billing_cycle)}${grText('gr-sub-next_renewal','Next renewal',r.next_renewal,'date')}${grText('gr-sub-paid_from','Account or card label',r.paid_from)}${grSelectField('gr-sub-status','Status',['keep','review','cancel'].map(k=>[k,k]),r.status)}${grText('gr-sub-client_name','Client to charge',r.client_name)}${grText('gr-sub-notes','Notes',r.notes)}</div><label class="gr-check"><input id="gr-sub-client_rebilled" type="checkbox" ${r.client_rebilled?'checked':''}> Charged to a client?</label><button class="btn btn-gold">Save subscription</button>${r.id?'<button type="button" class="btn btn-ghost" onclick="GR.editSubscription=null;grRefresh()">Cancel edit</button>':''}</fieldset></form></section>`;}
function grEditSubscription(id){if(!GR.subscriptions.some(r=>r.id===id))return;GR.editSubscription=id;grRefresh();}
function grSaveSubscription(event){event.preventDefault();return grRun(async()=>{const owner=grOwner(),old=GR.subscriptions.find(r=>r.id===GR.editSubscription),input={};for(const k of ['business','name','purpose','cost','billing_cycle','next_renewal','paid_from','client_name','status','notes'])input[k]=grValue('gr-sub-'+k);input.client_rebilled=document.getElementById('gr-sub-client_rebilled').checked;const r=GC.subscription(input);r.updated_at=new Date().toISOString();let q=old?sb.from('growth_subscriptions').update(r).eq('owner_id',owner).eq('id',old.id).eq('updated_at',old.updated_at):sb.from('growth_subscriptions').insert({owner_id:owner,id:crypto.randomUUID(),...r});const {data,error}=await q.select('*').maybeSingle();if(error||!data)throw error||Error('Subscription changed in another tab. Reload first.');if(grOwner()!==owner)return;GR.subscriptions=GR.subscriptions.filter(r=>r.id!==data.id).concat(data);GR.editSubscription=null;toast('Subscription saved');});}
function grFlow(){const w=grWeek(),r=GR.flowWeeks.find(r=>r.week_start===w)||{},m=GC.flowMilestones(GR.flowWeeks,new Date()),weekIndex=Math.max(0,Math.floor((new Date(w)-new Date(GR.settings.start_date))/604800000)),ramp=weekIndex===0?3:weekIndex===1?4:6;return `<section class="card"><h2>Steady Flow milestones</h2><p>By 15 December 2026: 20+ website sales a month and 4+ clients on £500+ monthly plans. Starter £369 · Standard £699 · Premium £999 · Core £600 / month · Growth £1,000 / month.</p><p>This month: ${m.monthly_sales} / 20 sales · ${m.qualifying_clients} / 4 qualifying monthly clients · ${m.active_clients} active clients · ${grMoney(m.mrr)} monthly income. Sales ramp this week: ${ramp}${weekIndex>2?'+':''}.</p>${grTable(['Week',...GR_METRICS.map(x=>x[1])],GR.flowWeeks.filter(r=>r.week_start<=w).sort((a,b)=>b.week_start.localeCompare(a.week_start)).map(r=>[esc(r.week_start),...GR_METRICS.map(([k])=>k==='mrr'?grMoney(r[k]):esc(r[k]))]))}<form onsubmit="grSaveFlow(event)"><fieldset ${GR.busy?'disabled':''}><div class="gr-fields">${GR_METRICS.map(([k,l])=>grField('gr-flow-'+k,l,r[k]||0)).join('')}</div><button class="btn btn-gold">Save Steady Flow week</button></fieldset></form><p class="small muted">Sales use the week’s starting month; clients use the latest entry.</p></section>`;}
function grSaveFlow(event){event.preventDefault();return grRun(async()=>{const owner=grOwner(),r={week_start:grWeek(),updated_at:new Date().toISOString()},old=GR.flowWeeks.find(r=>r.week_start===grWeek());for(const [k] of GR_METRICS){r[k]=Number(grValue('gr-flow-'+k));if(!Number.isFinite(r[k])||r[k]<0||(k!=='mrr'&&!Number.isInteger(r[k])))throw Error('Enter non-negative whole counts and a valid monthly income.');}if(r.clients_500_plus>r.monthly_clients_active)throw Error('Qualifying clients cannot exceed active monthly clients.');let q=old?sb.from('growth_flow_weeks').update(r).eq('owner_id',owner).eq('week_start',r.week_start).eq('updated_at',old.updated_at):sb.from('growth_flow_weeks').insert({owner_id:owner,...r});const {data,error}=await q.select('*').maybeSingle();if(error||!data)throw error||Error('Week changed in another tab. Reload first.');if(grOwner()!==owner)return;GR.flowWeeks=GR.flowWeeks.filter(x=>x.week_start!==r.week_start).concat(data);toast('Steady Flow metrics saved');});}
function grScoreboard(){const score=GC.scoreboard(grRows(),GR.settings,new Date());return `<section class="card"><h2>Combined £100k doubling scoreboard</h2><p>Combined profit, before pay. Double every 7–10 days; dates estimated.</p>${score.over_ten_days?'<p class="gr-notice">Over 10 days: review spend and hours.</p>':''}${grTable(['Week','Monday','Profit target','Running target','Actual profit','Actual running','Plan ahead'],score.targets.map(r=>[esc(r.week),esc(r.week_start),grMoney(r.target),grMoney(r.running_target),grMoney(r.actual),grMoney(r.running_actual),esc(r.warning)]))}<p class="small muted">Contractors: week 3; wider team: week 6. Targets are plans.</p></section>`;}
function grBusinessSettings(){return `<details class="card"><summary>Business accounts and shared Owner Pay</summary><p>£250 weekly across both businesses. Account names only.</p><form onsubmit="grSaveBusinesses(event)"><fieldset ${GR.busy?'disabled':''}><div class="gr-fields">${grField('gr-business-sf-pay','Steady Flow Owner Pay share (£)',(GR.businesses.find(b=>b.business==='sf')||{}).owner_pay_target||0)}${GR.businesses.map(b=>grText('gr-business-'+b.business+'-account',GR_BIZ[b.business]+' account label',b.account_label)).join('')}</div><p>SteadyWorks receives the remainder of £250.</p><button class="btn btn-gold">Save business settings</button></fieldset></form></details>`;}
function grSaveBusinesses(event){event.preventDefault();return grRun(async()=>{const owner=grOwner(),amount=Number(grValue('gr-business-sf-pay'));if(!Number.isFinite(amount)||amount<0||amount>250)throw Error('Choose a Steady Flow share from £0 to £250.');const {error}=await sb.rpc('growth_save_businesses',{p_sf_target:amount,p_sf_account:grValue('gr-business-sf-account'),p_sw_account:grValue('gr-business-sw-account')});if(error)throw error;if(grOwner()===owner)await grLoad();toast('Business settings saved');});}
function grReason(text){return ({'Inactive':'Turned off','Paused after two consecutive reds':'Paused after two weak weeks','Manual cap: no more good leads':'No more suitable leads','Two returns below 2x after spend increased':'Returns fell after raising spend','Booked hours exceed available hours':'More work than available hours','No entry for this week':'No figures for this week'})[text]||text;}
function grStatMoney(value){const text=grMoney(value);return `<strong class="${text.length>10?'gr-very-long-number':text.length>8?'gr-long-number':''}">${esc(text)}</strong>`;}
function grPotName(name){return `<span class="gr-pot-name"><i aria-hidden="true" style="background:${GC.potColours[name]||'#CBD5E1'}"></i>${esc(name)}</span>`;}
function grDate(value){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'Europe/London'}).format(new Date(value+'T12:00:00Z'));}
function grGoalName(){return Number(GR.settings.target_profit)===100000?'£100k':grMoney(GR.settings.target_profit);}
function grOverview(){return GC.overview(GR.channels,GR.weeks,GR.payments,GR.subscriptions,GR.businesses,GR.pots,GR.settings,GR.biz,new Date());}
function grBudgetRows(){return GC.budget(GR.payments,GR.biz,GR.budgetPeriod,GC.monday(GC.day(new Date())),GC.day(new Date())).filter(r=>r.pot!=='VAT'||GR.settings.vat_enabled||r.amount>0);}
function grLegend(rows,move){return `<ul class="gr-pot-legend">${rows.filter(r=>r.amount>0).map(r=>`<li><span>${grPotName(r.pot)}</span><strong>${move?'Move ':''}${grMoney(r.amount)}${move?' to '+esc(r.pot)+' pot':''}</strong></li>`).join('')}</ul>`;}
function grBudgetBody(){const rows=grBudgetRows(),total=GC.round(rows.reduce((n,r)=>n+r.amount,0));return total>0?`<div class="gr-budget-layout"><div class="gr-ring"><canvas id="gr-budget-chart" role="img" aria-label="Money set aside by pot"></canvas><div class="gr-ring-total"><strong>${grMoney(total)}</strong><span>set aside</span></div></div>${grLegend(rows,false)}</div>`:'<div class="gr-chart-empty"><strong>Your pots will appear here</strong><p>Save a payment to see the split.</p></div>';}
function grSetBudgetPeriod(period){if(!['week','all'].includes(period))return;GR.budgetPeriod=period;const body=document.getElementById('gr-budget-body');if(!body)return;body.innerHTML=grBudgetBody();for(const key of ['week','all']){const button=document.getElementById('gr-budget-'+key);if(button)button.setAttribute('aria-pressed',String(key===period));}grDrawBudget();}
function grBusinessTabs(){return `<div class="gr-business-tabs" role="tablist" aria-label="Business">${Object.entries(GR_BIZ).map(([b,l])=>`<button id="gr-biz-${b}" role="tab" aria-selected="${GR.biz===b}" tabindex="${GR.biz===b?'0':'-1'}" onclick="grTab('${b}')" onkeydown="grTabKey(event,'business','${b}')">${l}</button>`).join('')}</div>`;}
function grTabKey(event,group,value){const keys=group==='business'?Object.keys(GR_BIZ):GR_DETAIL_TABS.map(r=>r[0]);let index=keys.indexOf(value);if(event.key==='ArrowRight')index=(index+1)%keys.length;else if(event.key==='ArrowLeft')index=(index+keys.length-1)%keys.length;else if(event.key==='Home')index=0;else if(event.key==='End')index=keys.length-1;else return;event.preventDefault();if(group==='business')grTab(keys[index]);else grPanel(keys[index]);const el=document.getElementById((group==='business'?'gr-biz-':'gr-detail-')+keys[index]);if(el)el.focus();}
const GR_DETAIL_TABS=[['pots','Pots'],['channels','Weekly entries'],['subscriptions','Subscriptions'],['payments','Payments & voids'],['plan','Plan & sales'],['settings','Settings']];
function grSettings(){const s=GC.settings(GR.settings);return `<section class="card"><h2>Growth settings</h2><form onsubmit="grSaveSettings(event)"><fieldset ${GR.busy?'disabled':''}><div class="gr-fields">${[['target_profit','Profit goal (£)'],['reinvest_pct','Profit back into Growth (%)'],['tax_pct','Tax pot (%)'],['contractor_margin_pct','Keep after contractor (%)']].map(([k,l])=>grField('gr-setting-'+k,l,s[k])).join('')}${grText('gr-setting-start_date','Start date',s.start_date,'date')}</div><label class="gr-check"><input type="checkbox" id="gr-setting-vat_enabled" ${s.vat_enabled?'checked':''}> Set aside 20% of payments for VAT</label><p class="gr-help">Confirm Tax and VAT with your accountant.</p><button class="btn btn-gold">Save growth settings</button></fieldset></form></section>${grBusinessSettings()}<section class="card"><h2>Contractor check</h2><div class="gr-fields">${grField('gr-job-price','Job price (£)','','oninput="grContractor()"')}${grField('gr-contractor-cost','Contractor cost (£)','','oninput="grContractor()"')}</div><output id="gr-contractor-result">Contractor pay must stay within ${100-s.contractor_margin_pct}% of the price.</output></section>`;}
function grDetails(overview){let body;if(GR.panel==='pots')body=grPots();else if(GR.panel==='subscriptions')body=grSubscriptions();else if(GR.panel==='payments')body=grPayments();else if(GR.panel==='settings')body=grSettings();else if(GR.panel==='plan')body=grScoreboard()+(GR.biz!=='sw'?grFlow():'');else{const detailPlan=GC.fundedPlan(GR.channels,GR.weeks,GR.payments,GR.subscriptions,GR.businesses,GR.pots,GR.settings,grWeek()),rows=detailPlan.channels.filter(c=>GR.biz==='combined'||grBusiness(c.channel)===GR.biz);body=`<label class="gr-week-picker">Week starting Monday<input type="date" value="${grWeek()}" onchange="grSelect(this.value)"></label><div class="growth-grid">${rows.map(grCard).join('')}</div><p class="gr-help">${detailPlan.capacity.contractor_needed?'Book a contractor: work has been over 80% of your hours for two weeks.':detailPlan.capacity.known?'Hours checked. No extra contractor needed yet.':'Add two weeks of booked and available hours to check capacity.'} ${grMoney(detailPlan.unallocated)} needs a Growth destination.</p>`;}
 return `<details class="gr-details" ${GR.detailsOpen?'open':''} ontoggle="GR.detailsOpen=this.open"><summary><span>Details</span><small>Pots, weekly entries and settings</small></summary><div class="gr-detail-tabs" role="tablist" aria-label="Details">${GR_DETAIL_TABS.map(([k,l])=>`<button id="gr-detail-${k}" role="tab" aria-selected="${GR.panel===k}" tabindex="${GR.panel===k?'0':'-1'}" aria-controls="gr-detail-panel" onclick="grPanel('${k}')" onkeydown="grTabKey(event,'details','${k}')">${l}</button>`).join('')}</div><div id="gr-detail-panel" role="tabpanel" aria-labelledby="gr-detail-${GR.panel}">${body}</div></details>`;}
function grGoalCard(){const p=GC.forecast(grRows(),GR.settings,new Date()),score=GC.scoreboard(grRows(),GR.settings,new Date()),current=GC.monday(GC.day(new Date()));return `<section class="card gr-goal"><div class="gr-section-head"><h2>${grMoney(p.total_profit)} towards ${grMoney(GR.settings.target_profit)}</h2><span>${p.percent.toFixed(1)}%</span></div><progress value="${p.percent}" max="100" aria-label="Combined profit towards the goal"></progress><p class="gr-help">Both businesses · ${grMoney(p.remaining)} to go${p.projected_finish?' · at this pace: '+esc(grDate(p.projected_finish))+' '+p.projected_finish.slice(0,4):''}</p><ol class="gr-score-row" aria-label="Nine-week profit targets">${score.targets.map(r=>`<li ${r.week_start===current?'aria-current="step"':''}><span>Week ${r.week}</span><strong>${grMoney(r.target)}</strong><small>${grMoney(r.actual)} made</small></li>`).join('')}</ol>${score.over_ten_days?'<p class="gr-help gr-alert">Over 10 days. Review the plan below.</p>':''}</section>`;}
function grFridayCard(){const pay=GC.friday(GR.payments,GR.payouts,GR.biz,new Date());return `<section class="card gr-friday"><div><span class="gr-eyebrow">Friday, ${esc(grDate(pay.date))}</span><h2>${grMoney(pay.available)} for you</h2><p class="gr-help">${pay.available>0?'Ready in Owner Pay. Record it after you take it.':pay.paid>0?grMoney(pay.paid)+' already paid this week.':'Save payments to fill your Owner Pay pot.'}</p></div><button class="btn btn-ghost" id="gr-open-payout" onclick="grOpenModal('payout')" ${pay.available<=0||GR.busy?'disabled':''}>Mark as paid</button></section>`;}
function view_growth(){grDestroyCharts();if(!CURRENT_USER_ID||CURRENT_PROFILE.role!=='owner')return '<div class="empty-state">Owner access is required.</div>';
 if(GR.owner!==CURRENT_USER_ID||!GR.loaded){if(!GR.loading&&!GR.error)setTimeout(grLoad,0);return `<div class="empty-state">${GR.error?esc(GR.error)+'<p>Could not load Growth.</p><button class="btn btn-ghost" onclick="GR.error=null;grLoad()">Try again</button>':'Loading Growth…'}</div>`;}
 if(!GR.settings||!GR.channels.length||GR.businesses.length<2)return '<div class="card"><h2>Start Growth</h2><p>Create starting settings and pots.</p><button class="btn btn-gold" onclick="grInitialise()">Initialise Growth</button></div>';
 const o=grOverview(),series=GC.chartSeries(grRows(),GR.settings,GR.biz,GR.channels,new Date());grQueueCharts();return `<div class="growth" id="gr-dashboard">${grBusinessTabs()}<section class="card gr-this-week"><div class="gr-section-head"><div><span class="gr-eyebrow">${esc(grDate(o.week_start))}–${esc(grDate(GC.shift(o.week_start,6)))}</span><h2>This week</h2></div><span class="gr-light gr-${o.status}"><i aria-hidden="true"></i>${esc(o.label)}</span></div><div class="gr-week-numbers"><div><span>Lead spend</span>${grStatMoney(o.spend)}</div><div><span>Profit so far</span>${grStatMoney(o.profit)}</div><div><span>Combined target</span>${o.target==null?'<strong>Plan ended</strong>':grStatMoney(o.target)}</div></div><p class="gr-next-step">${esc(o.action)}</p>${GR.biz!=='combined'?'<small class="gr-help">The light checks both businesses and lead spend.</small>':''}</section><div class="gr-primary-actions"><button id="gr-open-payment" class="btn btn-gold" onclick="grOpenModal('payment')">I got paid</button><button id="gr-open-topup" class="btn btn-dark" onclick="grOpenModal('topup')">I topped up leads</button></div><div class="gr-overview"><section class="card gr-progress-card"><div class="gr-section-head"><h2>Profit towards ${esc(grGoalName())}</h2><span>${esc(GR_BIZ[GR.biz])}</span></div>${series.has_data?`<div class="gr-chart-key"><span><i class="gr-key-profit"></i>Profit made</span><span><i class="gr-key-target"></i>Combined target</span><span><i class="gr-key-goal"></i>${esc(grGoalName())} goal</span></div><div class="gr-line-chart"><canvas id="gr-progress-chart" role="img" aria-label="Weekly cumulative profit against the combined target and £100k goal"></canvas></div><h3 class="gr-weekly-heading">Profit each week</h3><div class="gr-weekly-chart"><canvas id="gr-weekly-chart" role="img" aria-label="Profit made each week"></canvas></div>`:'<div class="gr-chart-empty"><strong>Your progress starts here</strong><p>Add a payment or top-up to begin.</p></div>'}<p class="gr-help">${series.trimmed?'Latest 52 weeks. ':''}Profit includes unpaid work.</p></section><section class="card gr-budget-card"><div class="gr-section-head"><h2>Money in pots</h2><div class="gr-period" role="group" aria-label="Pot period"><button id="gr-budget-week" aria-pressed="${GR.budgetPeriod==='week'}" onclick="grSetBudgetPeriod('week')">This week</button><button id="gr-budget-all" aria-pressed="${GR.budgetPeriod==='all'}" onclick="grSetBudgetPeriod('all')">All time</button></div></div><div id="gr-budget-body">${grBudgetBody()}</div><p class="gr-help">Money set aside, not bank balances.</p></section></div>${grFridayCard()}${grGoalCard()}${grVatNear()?'<p class="gr-help gr-alert">Near the VAT threshold: ask your accountant.</p>':''}${grDetails(o)}<button class="btn btn-ghost gr-reload" onclick="grLoad()" ${GR.busy?'disabled':''}>Reload figures</button></div>`;
}

function grDestroyCharts(id){const ids=id?[id]:Object.keys(GR.charts);for(const key of ids){const chart=GR.charts[key];if(chart&&typeof chart.destroy==='function')chart.destroy();delete GR.charts[key];}}
function grChart(id,type,data,options){grDestroyCharts(id);const canvas=document.getElementById(id);if(!canvas)return;if(typeof Chart==='undefined'){const box=canvas.parentElement;if(box){let message=box.querySelector('.gr-chart-fallback');if(!message){message=document.createElement('p');message.className='gr-chart-fallback gr-help';message.textContent='The chart could not load. Your figures are still shown below.';box.appendChild(message);}}return;}
 GR.charts[id]=new Chart(canvas,{type,data,options:Object.assign({responsive:true,maintainAspectRatio:false,animation:false,color:'#CBD5E1',font:{family:'Segoe UI, sans-serif'},plugins:{legend:{display:false},tooltip:{backgroundColor:'#111827',titleColor:'#F8FAFC',bodyColor:'#E2E8F0',borderColor:'#334155',borderWidth:1,callbacks:{label:ctx=>ctx.dataset.label+': '+grMoney(ctx.parsed.y==null?ctx.parsed:ctx.parsed.y)}}}},options||{})});}
function grDrawBudget(){const rows=grBudgetRows().filter(r=>r.amount>0);if(!rows.length){grDestroyCharts('gr-budget-chart');return;}grChart('gr-budget-chart','doughnut',{labels:rows.map(r=>r.pot),datasets:[{label:'Set aside',data:rows.map(r=>r.amount),backgroundColor:rows.map(r=>r.colour),borderColor:'#141826',borderWidth:3,hoverOffset:3}]},{cutout:'74%',plugins:{legend:{display:false},tooltip:{backgroundColor:'#111827',bodyColor:'#E2E8F0',callbacks:{label:ctx=>ctx.label+': '+grMoney(ctx.parsed)}}}});}
function grRenderCharts(){if(currentRoute!=='growth'||GR.owner!==CURRENT_USER_ID||!GR.loaded||!document.getElementById('gr-dashboard')){grDestroyCharts();return;}const series=GC.chartSeries(grRows(),GR.settings,GR.biz,GR.channels,new Date()),points=series.points,labels=points.map(p=>p.label),ticks={color:'#94A3B8',font:{size:11},callback:value=>Math.abs(value)>=1000?'£'+(value/1000).toLocaleString('en-GB',{maximumFractionDigits:1})+'k':'£'+value},x={ticks:{color:'#94A3B8',maxRotation:0,autoSkip:true,maxTicksLimit:9},grid:{display:false},border:{display:false}};
 if(series.has_data){grChart('gr-progress-chart','line',{labels,datasets:[{label:'Profit made',data:points.map(p=>p.cumulative),borderColor:'#2DD4BF',backgroundColor:'#2DD4BF',pointRadius:3,pointHitRadius:15,borderWidth:3,spanGaps:false},{label:'Combined target',data:points.map(p=>p.target),borderColor:'#FBBF24',borderDash:[5,5],pointRadius:0,borderWidth:2},{label:grGoalName()+' goal',data:points.map(p=>p.goal),borderColor:'#64748B',borderDash:[2,5],pointRadius:0,borderWidth:1}]},{interaction:{mode:'index',intersect:false},scales:{x,y:{beginAtZero:true,ticks,grid:{color:'rgba(148,163,184,.12)'},border:{display:false}}}});
 grChart('gr-weekly-chart','bar',{labels,datasets:[{label:'Weekly profit',data:points.map(p=>p.profit),backgroundColor:points.map(p=>p.profit<0?'#FB7185':'#60A5FA'),borderRadius:3,maxBarThickness:28}]},{scales:{x,y:{beginAtZero:true,ticks:Object.assign({},ticks,{maxTicksLimit:3}),grid:{color:'rgba(148,163,184,.10)'},border:{display:false}}}});}
 grDrawBudget();if(GR.modal==='payment')grPaymentPreview();
 if(!GR.observer&&typeof MutationObserver!=='undefined'){GR.observer=new MutationObserver(()=>{if(currentRoute!=='growth'||!document.getElementById('gr-dashboard')){grDestroyCharts();grCloseModal(true);GR.observer.disconnect();GR.observer=null;}});GR.observer.observe(document.body,{childList:true,subtree:true});}
}
function grQueueCharts(){const version=++GR.chartVersion;setTimeout(()=>{if(version===GR.chartVersion)grRenderCharts();},0);}
function grEl(id){const modal=document.getElementById('gr-action-dialog');return modal&&typeof modal.querySelector==='function'&&modal.querySelector('[id="'+id+'"]')||document.getElementById(id);}
function grRequireData(){const owner=grOwner();if(GR.owner!==owner||!GR.loaded)throw Error('Reload Growth first.');return owner;}
function grOpenModal(kind){if(GR.busy)return;try{grRequireData();if(!['payment','topup','payout'].includes(kind))return;grCloseModal(true);GR.modal=kind;const titles={payment:'I got paid',topup:'I topped up leads',payout:'Mark as paid'},dialog=document.createElement('dialog');dialog.id='gr-action-dialog';dialog.className='growth gr-dialog';dialog.setAttribute('aria-labelledby','gr-modal-title');dialog.innerHTML=`<div class="gr-modal-head"><h2 id="gr-modal-title" tabindex="-1">${titles[kind]}</h2><button type="button" class="gr-modal-close" aria-label="Close" onclick="grCloseModal()">×</button></div><div class="gr-modal-body">${kind==='payment'?grPaymentForm():kind==='topup'?grTopupForm():grPayoutForm()}</div>`;dialog.addEventListener('cancel',event=>{if(GR.busy)event.preventDefault();});dialog.addEventListener('close',()=>grCloseModal());dialog.addEventListener('click',event=>{if(event.target===dialog&&!GR.busy){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)grCloseModal();}});document.body.appendChild(dialog);GR.bodyOverflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.showModal();dialog.querySelector('h2').focus({preventScroll:true});if(kind==='payment')grPaymentPreview();}catch(e){grCloseModal(true);toast(e.message,'⚠️');}}
function grCloseModal(quiet){const dialog=document.getElementById('gr-action-dialog');if(!dialog&&GR.modal==null)return;const kind=GR.modal;GR.modal=null;grDestroyCharts('gr-modal-chart');if(dialog){if(dialog.open)dialog.close();dialog.remove();}if(GR.bodyOverflow!=null){document.body.style.overflow=GR.bodyOverflow;GR.bodyOverflow=null;}if(!quiet){const opener=document.getElementById(kind==='topup'?'gr-open-topup':kind==='payout'?'gr-open-payout':'gr-open-payment');if(opener&&typeof opener.focus==='function')opener.focus({preventScroll:true});}}
function grSetModalBusy(){const dialog=document.getElementById('gr-action-dialog');if(!dialog||typeof dialog.querySelectorAll!=='function')return;for(const el of dialog.querySelectorAll('fieldset,.gr-modal-close'))el.disabled=GR.busy;}
function grPaymentForm(){const b=GR.biz==='combined'?'sw':GR.biz;return `<form onsubmit="grSavePayment(event)"><fieldset><div class="gr-fields">${grSelectField('gr-pay-business','Business',[['sf','Steady Flow'],['sw','SteadyWorks']],b,'onchange="grPaymentBusiness()"')}${grField('gr-pay-amount','Amount received (£)','','oninput="grPaymentPreview()" inputmode="decimal" required')}${grField('gr-pay-materials','Materials (£)',0,'oninput="grPaymentPreview()" inputmode="decimal"')}${grField('gr-pay-labour','Contractor (£)',0,'oninput="grPaymentPreview()" inputmode="decimal"')}${grField('gr-pay-lead_cost','Lead cost (£)',0,'oninput="grPaymentPreview()" inputmode="decimal"')}${grText('gr-pay-date','Date received',GC.day(new Date()),'date').replace('<input ','<input onchange="grPaymentPreview()" ')}${grSelectField('gr-pay-channel','Lead source',GR.channels.filter(c=>grBusiness(c)===b).map(c=>[c.id,c.name]),b==='sw'?'myjobquote':'steadyflow','onchange="grPaymentPreview()"')}${grSelectField('gr-pay-type','Payment for',b==='sw'?[['job','Job']]:[['website','Website'],['monthly','Monthly plan']],b==='sw'?'job':'website','onchange="grPaymentPreview()"')}</div><details class="gr-more"><summary>More options</summary>${grText('gr-pay-notes','Notes','')}<label>Owner Pay already set aside<input id="gr-pay-owner" type="text" readonly></label><label>Extra Growth still needed<input id="gr-pay-growth" type="text" readonly></label></details><div id="gr-split-result" aria-live="polite"><p class="gr-help">Enter an amount for the split.</p></div><p class="gr-help">Saving records this; move money yourself.</p><div class="gr-modal-foot"><button class="btn btn-gold" type="submit">Save payment</button></div></fieldset></form>`;}
function grPaymentBusiness(){const b=grValue('gr-pay-business');grEl('gr-pay-type').innerHTML=grOptions(b==='sw'?[['job','Job']]:[['website','Website'],['monthly','Monthly plan']],b==='sw'?'job':'website');grEl('gr-pay-channel').innerHTML=grOptions(GR.channels.filter(c=>grBusiness(c)===b).map(c=>[c.id,c.name]),b==='sw'?'myjobquote':'steadyflow');grPaymentPreview();}
function grPaymentPreview(){const output=grEl('gr-split-result');if(!output)return;grDestroyCharts('gr-modal-chart');try{const base=GC.splitContext(GR.payments,GR.subscriptions,GR.businesses,GR.pots,{business:grValue('gr-pay-business'),payment_date:grValue('gr-pay-date')},GR.settings);grEl('gr-pay-owner').value=grMoney(250-base.owner_total_needed)+' of £250';grEl('gr-pay-growth').value=grMoney(base.growth_needed);const p=grPaymentInput(),ctx=GC.splitContext(GR.payments,GR.subscriptions,GR.businesses,GR.pots,p,GR.settings),split=GC.splitPayment(p,ctx),rows=GC.pots.filter(k=>k!=='Main').map(pot=>({pot,amount:split.allocations[pot],colour:GC.potColours[pot]})).filter(r=>r.amount>0);grEl('gr-pay-owner').value=grMoney(250-ctx.owner_total_needed)+' of £250';grEl('gr-pay-growth').value=grMoney(ctx.growth_needed);output.innerHTML=`<div class="gr-split-head"><h3>Set this aside</h3><span>Profit ${grMoney(split.profit)}</span></div><div class="gr-modal-split"><div class="gr-modal-ring"><canvas id="gr-modal-chart" role="img" aria-label="Payment split by pot"></canvas></div><ul class="gr-move-lines">${rows.map(r=>`<li><i style="background:${r.colour}" aria-hidden="true"></i>Move <strong>${grMoney(r.amount)}</strong> to ${esc(r.pot)} pot</li>`).join('')}</ul></div>${GR.weeks.some(r=>Number(r.revenue)>Number(r.cash_received)&&GR.channels.some(c=>c.id===r.channel_id&&grBusiness(c)===p.business))?'<p class="gr-help">Clear matching unpaid entries in Details.</p>':''}${split.profit<0?'<p class="gr-help gr-alert">This payment lost money.</p>':''}${split.owner_shortfall>0?`<p class="gr-help">${grMoney(split.owner_shortfall)} left for Owner Pay this week.</p>`:''}${split.multiple==null?'':`<p class="gr-help">${split.multiple.toFixed(2)}x profit on lead cost · ${split.action==='double'?'Can grow':split.action==='halve'?'Halve lead spend':'Hold lead spend'}</p>`}`;grChart('gr-modal-chart','doughnut',{labels:rows.map(r=>r.pot),datasets:[{label:'Payment split',data:rows.map(r=>r.amount),backgroundColor:rows.map(r=>r.colour),borderColor:'#141826',borderWidth:2}]},{cutout:'65%',plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>ctx.label+': '+grMoney(ctx.parsed)}}}});}catch(e){output.textContent=Number(grEl('gr-pay-amount')&&grEl('gr-pay-amount').value)>0?e.message:'Enter an amount for the split.';}}
function grTopupForm(){const channels=GR.channels.filter(c=>GR.biz==='combined'||grBusiness(c)===GR.biz);return `<form onsubmit="grSaveTopup(event)"><fieldset><div class="gr-fields">${grSelectField('gr-topup-channel','Channel',channels.map(c=>[c.id,c.name]),channels[0]&&channels[0].id)}${grField('gr-topup-amount','Amount topped up (£)','','inputmode="decimal" required')}</div><p class="gr-help">This week only. Receipt lead costs use top-ups first.</p><div class="gr-modal-foot"><button class="btn btn-gold">Save top-up</button></div></fieldset></form>`;}
function grSaveTopup(event){event.preventDefault();return grRun(async()=>{const owner=grRequireData(),id=grValue('gr-topup-channel');if(!GR.channels.some(c=>c.id===id))throw Error('Choose a channel.');const r=GC.leadTopup(GR.weeks,GR.payments,id,grValue('gr-topup-amount'),GC.monday(GC.day(new Date())));await grPersistWeek(owner,r);if(grOwner()!==owner)return;grCloseModal();toast('Lead top-up saved');});}
async function grPersistWeek(owner,r){const old=GR.weeks.find(x=>x.channel_id===r.channel_id&&x.week_start===r.week_start),rows=GR.weeks.filter(x=>!(x.channel_id===r.channel_id&&x.week_start===r.week_start)).concat(r),result=GC.fundedPlan(GR.channels,rows,GR.payments,GR.subscriptions,GR.businesses,GR.pots,GR.settings,r.week_start).channels.find(x=>x.channel.id===r.channel_id),patch={...r,light:result.light,next_spend:result.next_spend,updated_at:new Date().toISOString()};delete patch.profit;let q=old?sb.from('growth_weeks').update(patch).eq('owner_id',owner).eq('channel_id',r.channel_id).eq('week_start',r.week_start).eq('updated_at',old.updated_at):sb.from('growth_weeks').insert({owner_id:owner,...patch});const {data,error}=await q.select('*').maybeSingle();if(error||!data)throw error||Error('This week changed. Reload before trying again.');if(grOwner()!==owner)return;GR.weeks=GR.weeks.filter(x=>!(x.channel_id===r.channel_id&&x.week_start===r.week_start)).concat(data);}
function grPayoutForm(){const pay=GC.friday(GR.payments,GR.payouts,GR.biz,new Date()),available=pay.parts.filter(p=>p.available>0);return `<form onsubmit="grSavePayout(event)"><fieldset><div class="gr-fields">${grSelectField('gr-payout-business','Business',available.map(p=>[p.business,GR_BIZ[p.business]]),available[0]&&available[0].business,'onchange="grPickPayout()"')}${grField('gr-payout-amount','Amount you took (£)',available[0]&&available[0].available,'inputmode="decimal" required')}</div><input id="gr-payout-date" type="hidden" value="${GC.day(new Date())}"><p class="gr-help">Records today’s pay, without transferring money.</p><div class="gr-modal-foot"><button class="btn btn-gold">Mark as paid</button></div></fieldset></form>`;}
function grPickPayout(){const part=GC.friday(GR.payments,GR.payouts,GR.biz,new Date()).parts.find(p=>p.business===grValue('gr-payout-business'));grEl('gr-payout-amount').value=part?part.available:0;}

// Clear private cache on logout or a changed login. No database action.
if(sb.auth&&typeof sb.auth.onAuthStateChange==='function')sb.auth.onAuthStateChange((event,session)=>{
 if(!session||GR.owner&&session.user.id!==GR.owner){grDestroyCharts();grCloseModal(true);GR.chartVersion++;if(GR.observer){GR.observer.disconnect();GR.observer=null;}GR.owner=null;GR.loaded=false;GR.settings=null;GR.channels=[];GR.weeks=[];GR.error=null;GR.selected=null;GR.businesses=[];GR.subscriptions=[];GR.payments=[];GR.pots=[];GR.flowWeeks=[];GR.payouts=[];GR.paymentRetry=null;GR.payoutRetry=null;GR.editSubscription=null;GR.detailsOpen=false;GR.panel='pots';}
});
